import{_ as a,c as i,a as s,o as n}from"./app-C_dHcy8Q.js";const o={};function t(r,e){return n(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="protoc-gen-croupier-skeleton" tabindex="-1"><a class="header-anchor" href="#protoc-gen-croupier-skeleton"><span>protoc-gen-croupier (skeleton)</span></a></h1><p>This plugin turns your .proto into Croupier &quot;packs&quot;: descriptors, UI schema, a manifest and an fds.pb. It can also bundle them into <code>pack.tgz</code>.</p><p>Status: initial skeleton. It derives defaults when no custom options are present. Update: custom options are supported via typed protobuf extensions (with a fallback parser for legacy descriptors).</p><h2 id="install-build" tabindex="-1"><a class="header-anchor" href="#install-build"><span>Install/Build</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">make croupier-plugin</span>
<span class="line"># binary at bin/protoc-gen-croupier</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="generate-with-protoc" tabindex="-1"><a class="header-anchor" href="#generate-with-protoc"><span>Generate with protoc</span></a></h2><p>Requires <code>protoc</code> on PATH.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PATH=&quot;$PWD/bin:$PATH&quot; \\</span>
<span class="line">protoc -I proto \\</span>
<span class="line">  --croupier_out=emit_pack=true:gen/croupier \\</span>
<span class="line">  proto/your/package/*.proto</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Artifacts go to <code>gen/croupier/</code>:</p><ul><li><code>manifest.json</code>: function list</li><li><code>descriptors/*.json</code>: function descriptors (transport/auth/semantics)</li><li><code>ui/*.schema.json</code> and <code>ui/*.uischema.json</code>: JSON Schema and UI Schema for requests</li><li><code>fds.pb</code>: FileDescriptorSet (types)</li><li><code>pack.tgz</code>: all the above bundled (if <code>emit_pack=true</code>)</li></ul><h2 id="provider-manifest-emit-manifest" tabindex="-1"><a class="header-anchor" href="#provider-manifest-emit-manifest"><span>Provider manifest (emit_manifest)</span></a></h2><p>When <code>emit_manifest=true</code>, the plugin additionally generates:</p><ul><li><code>manifest.json</code> with a top-level <code>provider</code> block + richer <code>functions[]</code> entries (request/response schema refs)</li><li><code>schema/*.json</code>: JSON Schema files for request/response messages when resolvable</li><li><code>descriptors.fds</code>: FileDescriptorSet in <code>.fds</code> form (same content as <code>fds.pb</code>)</li></ul><p>Suggested params: <code>provider_id</code>, <code>provider_version</code>, <code>provider_lang</code>, <code>provider_sdk</code>, <code>provider_description</code></p><p>Example:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PATH=&quot;$PWD/bin:$PATH&quot; \\</span>
<span class="line">protoc -I proto \\</span>
<span class="line">  --croupier_out=emit_pack=true,emit_manifest=true,provider_id=player,provider_version=1.0.0:gen/croupier \\</span>
<span class="line">  proto/examples/games/player/v1/player.proto</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="inspect-validate-packs" tabindex="-1"><a class="header-anchor" href="#inspect-validate-packs"><span>Inspect &amp; Validate packs</span></a></h2><p>Use the unified CLI to inspect or validate a generated pack:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># show manifest and list files</span>
<span class="line">./bin/croupier packs inspect gen/croupier/pack.tgz</span>
<span class="line"></span>
<span class="line"># validate presence of manifest/fds/descriptors for each function</span>
<span class="line">./bin/croupier packs validate gen/croupier/pack.tgz</span>
<span class="line"># or validate an extracted directory</span>
<span class="line">./bin/croupier packs validate gen/croupier</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If you prefer a one-liner with checks, use:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">./scripts/generate-pack.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>This script builds <code>protoc-gen-croupier</code> if needed and invokes <code>protoc</code> against all files under <code>proto/</code>.</p><h2 id="generate-with-buf-optional" tabindex="-1"><a class="header-anchor" href="#generate-with-buf-optional"><span>Generate with buf (optional)</span></a></h2><p>Buf will look for <code>protoc-gen-croupier</code> on PATH.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PATH=&quot;$PWD/bin:$PATH&quot; buf generate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Note: remote plugins in <code>buf.gen.yaml</code> may require network. You can remove them if offline.</p><h2 id="defaults" tabindex="-1"><a class="header-anchor" href="#defaults"><span>Defaults</span></a></h2><ul><li>function_id: <code>&lt;package&gt;.&lt;Service&gt;.&lt;Method&gt;</code> lowercased</li><li>version: <code>1.0.0</code></li><li>category: second-to-last segment of package (e.g., <code>games.player.v1</code> → <code>player</code>)</li><li>transport: protobuf (pb-json UI, Server encodes to pb-bin)</li><li>semantics: mode=query, route=lb, timeout=30s, idempotency_key=false</li><li>auth: permission=function_id, two_person_rule=false</li><li>placement: agent</li><li>outputs: a default <code>json.view</code></li></ul><h2 id="next-steps" tabindex="-1"><a class="header-anchor" href="#next-steps"><span>Next steps</span></a></h2><ul><li>Parse map-style options (labels/enum_map) – basic support added; improve nested parsing</li><li>UI annotations enrich generated UI Schema – widget/label/placeholder/sensitive/show_if/required_if supported</li><li>Enum detection in JSON Schema – supported (string names + enum list)</li><li>Map fields in JSON Schema – supported (additionalProperties)</li><li>Per-method route/approval/placement/timeout – supported</li><li>Pack signature and validation</li></ul><h2 id="supported-custom-options-current" tabindex="-1"><a class="header-anchor" href="#supported-custom-options-current"><span>Supported custom options (current)</span></a></h2><ul><li>Method option <code>(croupier.options.v1.function)</code>: <ul><li><code>function_id</code>, <code>version</code>, <code>category</code>, <code>risk</code>, <code>route</code>, <code>timeout</code>, <code>two_person_rule</code>, <code>placement</code>, <code>mode</code>, <code>idempotency_key</code></li></ul></li><li>Field option <code>(croupier.options.v1.ui)</code>: <ul><li><code>widget</code>, <code>label</code>, <code>placeholder</code>, <code>sensitive</code>, <code>show_if</code>, <code>required_if</code>, <code>enum_map</code></li></ul></li></ul><p>Example:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">rpc Ban(BanRequest) returns (BanResponse) {</span>
<span class="line">  option (croupier.options.v1.function) = {</span>
<span class="line">    function_id: &quot;player.ban&quot; version: &quot;1.2.0&quot; risk: &quot;high&quot;</span>
<span class="line">    route: &quot;lb&quot; timeout: &quot;30s&quot; two_person_rule: true placement: &quot;agent&quot;</span>
<span class="line">    mode: &quot;command&quot; idempotency_key: true</span>
<span class="line">  };</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">message BanRequest {</span>
<span class="line">  string player_id = 1 [(croupier.options.v1.ui) = { label: &quot;玩家ID&quot;, widget: &quot;input&quot; }];</span>
<span class="line">  string reason    = 2 [(croupier.options.v1.ui) = { widget: &quot;textarea&quot;, placeholder: &quot;原因&quot; }];</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>Pack signature and validation</li></ul>`,35)])])}const l=a(o,[["render",t]]),d=JSON.parse('{"path":"/generator.html","title":"protoc-gen-croupier (skeleton)","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1766533527000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":6,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"8d5bb6849c1d80a3c68c5de32f59f854cc324a13","time":1766533527000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"P0/P1: proto-first generator, manifest, jobs routing, TLS"},{"hash":"228147054e4f1a15cada6bb3a8af42c4128040fb","time":1762002341000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: commit local changes"},{"hash":"2850102635c30770039d04ddc769f91e4129703e","time":1761962609000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: rename Core concept to Server across README and docs"},{"hash":"cd7ea4cd782c2ba189fb02ccdfd2b7a62c040502","time":1761962328000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(generator): document supported function/ui options and example usage"},{"hash":"e8a1db0b0681023a2e099c0d3b75bb20c53af5b0","time":1761962226000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(generator): update status to reflect options parsing, enum/map support"},{"hash":"d81fa3c83dd2ab507242a073b1073e02129fd1e2","time":1761961711000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: add protoc-gen-croupier usage and pack artifacts overview"}]},"filePathRelative":"generator.md"}');export{l as comp,d as data};
